-- Enable UUID extension if not already enabled
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 1. Tabela: Plano de Contas (account_accounts)
CREATE TABLE IF NOT EXISTS account_accounts (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code VARCHAR(20) NOT NULL,
    name VARCHAR(255) NOT NULL,
    account_type VARCHAR(50) NOT NULL CHECK (account_type IN (
        'asset_receivable', -- A Receber
        'asset_cash',       -- Caixa e Bancos
        'asset_current',    -- Ativo Circulante
        'asset_non_current',-- Ativo Não Circulante
        'liability_payable',-- A Pagar
        'liability_current',-- Passivo Circulante
        'liability_non_current', -- Passivo Não Circulante
        'equity',           -- Patrimônio Líquido
        'income',           -- Receitas
        'income_other',     -- Outras Receitas
        'expense',          -- Despesas
        'expense_depreciation', -- Depreciação
        'cost_of_revenue',  -- Custo da Mercadoria Vendida (CMV)
        'off_balance'       -- Contas de Compensação
    )),
    reconcile BOOLEAN DEFAULT FALSE, -- Se permite conciliação (ex: A Receber/A Pagar)
    note TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    UNIQUE(code)
);

-- 2. Tabela: Diários (account_journals)
CREATE TABLE IF NOT EXISTS account_journals (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    code VARCHAR(10) NOT NULL,
    type VARCHAR(50) NOT NULL CHECK (type IN ('sale', 'purchase', 'cash', 'bank', 'general')),
    default_account_id BIGINT REFERENCES account_accounts(id), -- Conta padrão (ex: conta do banco para diário de banco)
    sequence INTEGER DEFAULT 10,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    UNIQUE(code)
);

-- 3. Tabela: Lançamentos Contábeis - Cabeçalho (account_moves)
CREATE TABLE IF NOT EXISTS account_moves (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(255) NOT NULL DEFAULT '/', -- Será preenchido por trigger/sequence, ex: FAT/2023/001
    date DATE NOT NULL DEFAULT CURRENT_DATE,
    ref VARCHAR(255), -- Referência externa (ex: Nº da Nota Fiscal)
    journal_id BIGINT NOT NULL REFERENCES account_journals(id),
    state VARCHAR(20) DEFAULT 'draft' CHECK (state IN ('draft', 'posted', 'cancel')),
    move_type VARCHAR(50) DEFAULT 'entry' CHECK (move_type IN (
        'entry',        -- Lançamento Manual Diverso
        'out_invoice',  -- Fatura Cliente (Venda)
        'out_refund',   -- Reembolso Cliente
        'in_invoice',   -- Fatura Fornecedor (Compra)
        'in_refund',    -- Reembolso Fornecedor
        'out_receipt',  -- Recibo Venda
        'in_receipt'    -- Recibo Compra
    )),
    partner_id UUID REFERENCES auth.users(id), -- Opcional: link com usuário do sistema
    partner_name VARCHAR(255), -- Nome do parceiro (Cliente/Fornecedor) se não for usuário
    amount_total NUMERIC(15,2) DEFAULT 0.00, -- Soma total (informativo/cache)
    narration TEXT, -- Notas internas
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    loja_id BIGINT -- Multi-loja support
);

-- 4. Tabela: Itens do Lançamento (account_move_lines)
CREATE TABLE IF NOT EXISTS account_move_lines (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    move_id BIGINT NOT NULL REFERENCES account_moves(id) ON DELETE CASCADE,
    journal_id BIGINT NOT NULL REFERENCES account_journals(id), -- Denormalizado para performance
    account_id BIGINT NOT NULL REFERENCES account_accounts(id),
    name VARCHAR(255), -- Descrição da linha
    debit NUMERIC(15,2) DEFAULT 0.00,
    credit NUMERIC(15,2) DEFAULT 0.00,
    balance NUMERIC(15,2) GENERATED ALWAYS AS (debit - credit) STORED,
    date DATE NOT NULL, -- Denormalizado do move
    date_maturity DATE, -- Data de vencimento (para A Pagar/A Receber)
    partner_id UUID REFERENCES auth.users(id),
    partner_name VARCHAR(255),
    reconciled BOOLEAN DEFAULT FALSE,
    full_reconcile_id BIGINT, -- Futuro: ID da reconciliação
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Indexes
CREATE INDEX idx_account_accounts_code ON account_accounts(code);
CREATE INDEX idx_account_moves_date ON account_moves(date);
CREATE INDEX idx_account_moves_state ON account_moves(state);
CREATE INDEX idx_account_move_lines_account_id ON account_move_lines(account_id);
CREATE INDEX idx_account_move_lines_move_id ON account_move_lines(move_id);
CREATE INDEX idx_account_move_lines_date ON account_move_lines(date);

-- RLS Policies
ALTER TABLE account_accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE account_journals ENABLE ROW LEVEL SECURITY;
ALTER TABLE account_moves ENABLE ROW LEVEL SECURITY;
ALTER TABLE account_move_lines ENABLE ROW LEVEL SECURITY;

-- Policy: Authenticated users can view all (for now)
CREATE POLICY "Enable read access for authenticated users" ON account_accounts FOR SELECT TO authenticated USING (true);
CREATE POLICY "Enable read access for authenticated users" ON account_journals FOR SELECT TO authenticated USING (true);
CREATE POLICY "Enable read access for authenticated users" ON account_moves FOR SELECT TO authenticated USING (true);
CREATE POLICY "Enable read access for authenticated users" ON account_move_lines FOR SELECT TO authenticated USING (true);

-- Policy: Only admin/finance can insert/update (Simplified to authenticated for prototype)
CREATE POLICY "Enable write access for authenticated users" ON account_accounts FOR ALL TO authenticated USING (true);
CREATE POLICY "Enable write access for authenticated users" ON account_journals FOR ALL TO authenticated USING (true);
CREATE POLICY "Enable write access for authenticated users" ON account_moves FOR ALL TO authenticated USING (true);
CREATE POLICY "Enable write access for authenticated users" ON account_move_lines FOR ALL TO authenticated USING (true);

-- Trigger para atualizar updated_at
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ language 'plpgsql';

CREATE TRIGGER update_account_accounts_modtime BEFORE UPDATE ON account_accounts FOR EACH ROW EXECUTE PROCEDURE update_updated_at_column();
CREATE TRIGGER update_account_journals_modtime BEFORE UPDATE ON account_journals FOR EACH ROW EXECUTE PROCEDURE update_updated_at_column();
CREATE TRIGGER update_account_moves_modtime BEFORE UPDATE ON account_moves FOR EACH ROW EXECUTE PROCEDURE update_updated_at_column();

