-- Scanner: entrada/saída por bip não pode mais travar por "lote morto".
--
-- Contexto: o QR congela o id do lote no momento da impressão. Como `lotes`
-- é duplicado por código (mesma data vira vários ids) e os duplicados são
-- deletados depois, a FK `etiquetas_qr.lote_id` (ON DELETE SET NULL) zera o
-- vínculo da linha — mas o QR continua apontando o id antigo. Ao dar entrada,
-- o Scanner gravava esse id morto em `movimentacoes.lote_id` (FK NO ACTION) e
-- o banco rejeitava (`movimentacoes_lote_id_fkey`), travando a caixa.
--
-- Solução: resolver SEMPRE um lote VIVO pela própria etiqueta — prioriza o
-- lote_id da linha; se morto/ausente, re-vincula por código + validade (o
-- mesmo lote existe sob outro id); se ainda assim não houver, grava NULL
-- (a entrada acontece e o código do lote fica na observação).

-- ── Helper reutilizável: lote vivo a partir do UID da etiqueta ───────────────
CREATE OR REPLACE FUNCTION public.resolver_lote_etiqueta(p_uid text)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $fn$
DECLARE
    v_row_lote uuid;
    v_codigo   text;
    v_validade date;
    v_pid      integer;
    v_result   uuid;
BEGIN
    SELECT lote_id, lote_codigo_snapshot, lote_validade_snapshot, produto_master_id
      INTO v_row_lote, v_codigo, v_validade, v_pid
      FROM public.etiquetas_qr
     WHERE uid = p_uid;

    -- 1) lote da linha, se ainda existe (caminho feliz)
    IF v_row_lote IS NOT NULL
       AND EXISTS (SELECT 1 FROM public.lotes WHERE id = v_row_lote) THEN
        RETURN v_row_lote;
    END IF;

    -- 2) re-vincular por código + validade (+ produto) — desempata pelo mais recente
    IF v_codigo IS NOT NULL THEN
        SELECT id INTO v_result
          FROM public.lotes
         WHERE codigo = v_codigo
           AND (v_pid IS NULL OR produto_id = v_pid)
           AND (v_validade IS NULL OR data_validade = v_validade)
         ORDER BY created_at DESC
         LIMIT 1;
        IF v_result IS NOT NULL THEN
            RETURN v_result;
        END IF;

        -- fallback: só por código + produto (ignora validade)
        SELECT id INTO v_result
          FROM public.lotes
         WHERE codigo = v_codigo
           AND (v_pid IS NULL OR produto_id = v_pid)
         ORDER BY created_at DESC
         LIMIT 1;
        IF v_result IS NOT NULL THEN
            RETURN v_result;
        END IF;
    END IF;

    -- 3) nada encontrado → NULL (entrada grava sem vínculo de lote)
    RETURN NULL;
END;
$fn$;

GRANT EXECUTE ON FUNCTION public.resolver_lote_etiqueta(text) TO authenticated, anon, service_role;

-- ── RPC do Scanner: resolve lote vivo + marca duplicado ──────────────────────
CREATE OR REPLACE FUNCTION public.bipar_lote_scanner(p_loja_id integer, p_tipo text, p_itens jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_usuario_id integer;
    v_item jsonb;
    v_id text;
    v_pid integer;
    v_uid text;
    v_lote_id uuid;
    v_qty numeric;
    v_disp numeric;
    v_interna numeric;
    v_tipo_embalagem text;
    v_embalagem_nome text;
    v_lote text;
    v_payload jsonb;
    v_bip jsonb;
    v_saldo_anterior numeric;
    v_saldo_novo numeric;
    v_motivo text;
    v_observacoes text;
    v_resultados jsonb := '[]'::jsonb;
    v_ok integer := 0;
    v_err integer := 0;
BEGIN
    BEGIN
        v_usuario_id := public.get_usuario_id_from_auth(auth.uid());
    EXCEPTION WHEN OTHERS THEN
        v_usuario_id := NULL;
    END;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_itens)
    LOOP
        v_id := v_item->>'id';
        BEGIN
            v_pid := (v_item->>'pid')::integer;
            v_uid := NULLIF(v_item->>'uid', '');
            -- lote do payload é só dica; lid malformado não pode derrubar o item
            BEGIN
                v_lote_id := NULLIF(v_item->>'lote_id', '')::uuid;
            EXCEPTION WHEN OTHERS THEN
                v_lote_id := NULL;
            END;
            v_qty := (v_item->>'qty')::numeric;
            v_tipo_embalagem := NULLIF(v_item->>'tipo_embalagem', '');
            v_embalagem_nome := NULLIF(v_item->>'embalagem_nome', '');
            v_lote := NULLIF(v_item->>'lote', '');
            v_payload := v_item->'payload';

            IF v_uid IS NOT NULL THEN
                BEGIN
                    v_bip := public.bipar_etiqueta(
                        v_uid,
                        CASE WHEN p_tipo = 'entrada' THEN 'entrada' ELSE 'saida' END,
                        jsonb_build_object(
                            'loja_id', p_loja_id,
                            'referencia_tipo', 'scanner_lote',
                            'payload', v_payload
                        )
                    );
                EXCEPTION WHEN OTHERS THEN
                    v_bip := NULL;
                END;

                -- IDEMPOTENCIA: etiqueta ja contada nesta etapa (bip duplicado) → nao lanca de novo.
                IF v_bip IS NOT NULL AND COALESCE((v_bip->>'ok')::boolean, true) = false THEN
                    v_resultados := v_resultados || jsonb_build_object(
                        'id', v_id, 'ok', false, 'duplicado', true,
                        'erro', COALESCE(NULLIF(v_bip->>'erro',''),
                                         CASE WHEN p_tipo = 'entrada'
                                              THEN 'Esta caixa já teve entrada registrada'
                                              ELSE 'Esta caixa já teve saída registrada' END)
                    );
                    v_err := v_err + 1;
                    CONTINUE;
                END IF;

                -- QTY AUTORITATIVA: o que a caixa realmente tem.
                SELECT quantidade_disponivel, quantidade_interna
                  INTO v_disp, v_interna
                  FROM etiquetas_qr
                 WHERE uid = v_uid;
                v_qty := COALESCE(NULLIF(v_disp, 0), NULLIF(v_interna, 0), v_qty);
            END IF;

            IF v_qty IS NULL OR v_qty <= 0 THEN
                RAISE EXCEPTION '%', CASE WHEN p_tipo='entrada'
                    THEN 'Sem quantidade para dar entrada'
                    ELSE 'Container ja vazio — nada para dar saida' END;
            END IF;

            SELECT COALESCE(quantidade_atual, 0)
              INTO v_saldo_anterior
              FROM estoque
             WHERE produto_master_id = v_pid
               AND loja_id = p_loja_id;

            v_saldo_anterior := COALESCE(v_saldo_anterior, 0);

            IF p_tipo = 'entrada' THEN
                v_saldo_novo := v_saldo_anterior + v_qty;
            ELSE
                v_saldo_novo := GREATEST(0, v_saldo_anterior - v_qty);
            END IF;

            -- LOTE VIVO: prioriza a linha da etiqueta; re-vincula por código/validade;
            -- senão NULL. Nunca grava id de lote inexistente (evita FK e não trava).
            IF v_uid IS NOT NULL THEN
                v_lote_id := public.resolver_lote_etiqueta(v_uid);
            END IF;
            IF v_lote_id IS NOT NULL
               AND NOT EXISTS (SELECT 1 FROM public.lotes WHERE id = v_lote_id) THEN
                v_lote_id := NULL;
            END IF;

            v_motivo := CASE WHEN p_tipo = 'entrada' THEN 'scanner_lote' ELSE 'saida_inteira' END;
            v_observacoes := (CASE WHEN p_tipo = 'entrada' THEN 'Entrada' ELSE 'Saída inteira' END)
                || ' via Scanner QR — ' || COALESCE(v_tipo_embalagem, 'container')
                || ' de ' || v_qty::text || ' ' || COALESCE(v_embalagem_nome, 'un')
                || ' · Lote ' || COALESCE(v_lote, '—');

            INSERT INTO movimentacoes (
                produto_master_id, tipo_movimentacao, quantidade,
                quantidade_anterior, quantidade_nova, motivo, observacoes,
                data_movimentacao, loja_id, lote_id, etiqueta_qr_uid, usuario_id
            ) VALUES (
                v_pid, p_tipo, v_qty,
                v_saldo_anterior, v_saldo_novo, v_motivo, v_observacoes,
                now(), p_loja_id, v_lote_id, v_uid, v_usuario_id
            );

            v_resultados := v_resultados || jsonb_build_object('id', v_id, 'ok', true);
            v_ok := v_ok + 1;

        EXCEPTION WHEN OTHERS THEN
            v_resultados := v_resultados || jsonb_build_object('id', v_id, 'ok', false, 'erro', SQLERRM);
            v_err := v_err + 1;
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'ok', true,
        'processados', v_ok,
        'falhas', v_err,
        'resultados', v_resultados
    );
END;
$function$;

-- =========================================================================
-- Fix bipar_etiqueta: aceitar payload com chaves longas (pid/lid/lote/qty/emb)
-- além das curtas (p/l/c/q/n) usadas no QR comprimido.
--
-- Bug: o frontend (PickingBipModal/SeparacaoBipModal/EntradaBipModal) envia
-- ScannedPayload com chaves longas, mas a versão original da RPC só lia as
-- curtas — fazendo backfill falhar pra etiquetas antigas (geradas antes do
-- PR1, sem row em etiquetas_qr) com mensagem "Etiqueta não cadastrada e sem
-- payload para backfill", interpretada pelo operador como "validade não
-- reconhecida".
--
-- Esta migration recria bipar_etiqueta usando COALESCE em ambas as chaves.
-- =========================================================================

CREATE OR REPLACE FUNCTION public.bipar_etiqueta(
  p_uid       text,
  p_etapa     text,
  p_contexto  jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_etiqueta            public.etiquetas_qr%ROWTYPE;
  v_user_id             uuid := auth.uid();
  v_user_nome           text;
  v_status_anterior     text;
  v_status_novo         text;
  v_loja_id             integer;
  v_alertas             jsonb := '[]'::jsonb;
  v_referencia_tipo     text;
  v_referencia_id       text;
  v_payload             jsonb;
  v_pid_text            text;
  v_pid_int             integer;
  v_lote_uuid           uuid;
  v_produto_nome        text;
  v_lote_codigo         text;
  v_lote_validade       date;
BEGIN
  IF p_etapa NOT IN ('separacao','conferencia','entrada','saida','consumo','descarte') THEN
    RETURN jsonb_build_object('ok', false, 'erro', 'Etapa inválida: ' || p_etapa);
  END IF;

  SELECT COALESCE(raw_user_meta_data->>'nome', email)
    INTO v_user_nome
    FROM auth.users WHERE id = v_user_id;

  v_loja_id         := NULLIF(p_contexto->>'loja_id','')::integer;
  v_referencia_tipo := p_contexto->>'referencia_tipo';
  v_referencia_id   := p_contexto->>'referencia_id';
  v_payload         := p_contexto->'payload';

  SELECT * INTO v_etiqueta FROM public.etiquetas_qr WHERE uid = p_uid;

  -- ===== BACKFILL — etiqueta antiga (sem row), mas QR contém produto =====
  IF NOT FOUND THEN
    IF v_payload IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta não cadastrada e sem payload para backfill');
    END IF;

    -- Aceita chaves longas (pid/lid/lote/qty/emb) ou curtas (p/l/c/q/n)
    v_pid_text := COALESCE(v_payload->>'pid', v_payload->>'p');
    IF v_pid_text IS NULL OR v_pid_text = '' THEN
      RETURN jsonb_build_object('ok', false, 'erro', 'Etiqueta não cadastrada e payload sem produto');
    END IF;
    v_pid_int   := v_pid_text::integer;
    v_lote_uuid := NULLIF(COALESCE(v_payload->>'lid', v_payload->>'l'),'')::uuid;

    -- Busca snapshots em separado (evita UPDATE...FROM com alias da tabela alvo)
    SELECT nome INTO v_produto_nome FROM public.produtos_master WHERE id = v_pid_int;
    IF v_lote_uuid IS NOT NULL THEN
      SELECT codigo, data_validade INTO v_lote_codigo, v_lote_validade
        FROM public.lotes WHERE id = v_lote_uuid;
    END IF;

    INSERT INTO public.etiquetas_qr (
      uid, produto_master_id, lote_id, embalagem_nome, quantidade_interna,
      produto_nome_snapshot, lote_codigo_snapshot, lote_validade_snapshot,
      loja_origem_id, loja_atual_id, status, backfilled, qr_payload
    ) VALUES (
      p_uid,
      v_pid_int,
      v_lote_uuid,
      COALESCE(v_payload->>'emb', v_payload->>'n'),
      COALESCE(NULLIF(COALESCE(v_payload->>'qty', v_payload->>'q'),'')::numeric, 1),
      v_produto_nome,
      v_lote_codigo,
      v_lote_validade,
      NULL, v_loja_id,
      CASE p_etapa
        WHEN 'separacao'   THEN 'separada'
        WHEN 'conferencia' THEN 'conferida'
        WHEN 'entrada'     THEN 'recebida'
        WHEN 'saida'       THEN 'em_transito'
        WHEN 'consumo'     THEN 'consumida'
        WHEN 'descarte'    THEN 'descartada'
      END,
      true,
      v_payload
    )
    RETURNING * INTO v_etiqueta;

    v_alertas := v_alertas || jsonb_build_array('Etiqueta antiga registrada retroativamente (backfill)');

    INSERT INTO public.etiquetas_qr_eventos (
      etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
      loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
    ) VALUES (
      p_uid, 'backfilled', 'backfill', NULL, v_etiqueta.status,
      v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
      jsonb_build_object('etapa_origem', p_etapa, 'payload', v_payload)
    );

    RETURN jsonb_build_object(
      'ok', true,
      'etiqueta', to_jsonb(v_etiqueta),
      'status_anterior', NULL,
      'status_novo', v_etiqueta.status,
      'alertas', v_alertas,
      'backfilled', true
    );
  END IF;

  -- ===== Etiqueta encontrada =====
  v_status_anterior := v_etiqueta.status;

  IF v_etiqueta.status = 'descartada' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'erro', 'Etiqueta descartada' ||
              CASE WHEN v_etiqueta.replaced_by_uid IS NOT NULL
                   THEN ' (substituída por ' || v_etiqueta.replaced_by_uid || ')'
                   ELSE ''
              END,
      'etiqueta', to_jsonb(v_etiqueta)
    );
  END IF;

  v_status_novo := CASE p_etapa
    WHEN 'separacao' THEN
      CASE WHEN v_etiqueta.status IN ('gerada','recebida','em_separacao') THEN 'separada'
           ELSE NULL END
    WHEN 'conferencia' THEN
      CASE WHEN v_etiqueta.status IN ('separada','gerada','recebida') THEN 'conferida'
           ELSE NULL END
    WHEN 'saida' THEN
      CASE WHEN v_etiqueta.status IN ('conferida','separada','gerada') THEN 'em_transito'
           ELSE NULL END
    WHEN 'entrada' THEN
      CASE WHEN v_etiqueta.status IN ('em_transito','gerada','conferida') THEN 'recebida'
           WHEN v_etiqueta.status = 'recebida' AND v_loja_id IS DISTINCT FROM v_etiqueta.loja_atual_id THEN 'recebida'
           ELSE NULL END
    WHEN 'consumo'   THEN 'consumida'
    WHEN 'descarte'  THEN 'descartada'
  END;

  IF v_status_novo IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'erro', format('Etiqueta %s já está com status "%s" — bip duplicado nesta etapa',
                     p_uid, v_status_anterior),
      'etiqueta', to_jsonb(v_etiqueta)
    );
  END IF;

  IF v_etiqueta.lote_validade_snapshot IS NOT NULL
     AND v_etiqueta.lote_validade_snapshot < CURRENT_DATE THEN
    v_alertas := v_alertas || jsonb_build_array(
      format('LOTE VENCIDO em %s', to_char(v_etiqueta.lote_validade_snapshot,'DD/MM/YYYY'))
    );
  END IF;

  UPDATE public.etiquetas_qr SET
    status        = v_status_novo,
    loja_atual_id = COALESCE(v_loja_id, loja_atual_id)
  WHERE uid = p_uid
  RETURNING * INTO v_etiqueta;

  INSERT INTO public.etiquetas_qr_eventos (
    etiqueta_uid, tipo_evento, etapa, status_anterior, status_novo,
    loja_id, usuario_id, usuario_nome, referencia_tipo, referencia_id, metadata
  ) VALUES (
    p_uid, 'bipada_' || p_etapa, p_etapa, v_status_anterior, v_status_novo,
    v_loja_id, v_user_id, v_user_nome, v_referencia_tipo, v_referencia_id,
    p_contexto - 'payload'
  );

  RETURN jsonb_build_object(
    'ok', true,
    'etiqueta', to_jsonb(v_etiqueta),
    'status_anterior', v_status_anterior,
    'status_novo', v_status_novo,
    'alertas', v_alertas,
    'backfilled', false
  );
END;
$$;

COMMENT ON FUNCTION public.bipar_etiqueta IS
  'Validação atômica de bip. Aceita payload com chaves longas (pid/lid/qty/emb) ou curtas (p/l/q/n) — backfill robusto pra etiquetas antigas. Retorna {ok, etiqueta, status_anterior, status_novo, alertas, backfilled, erro}.';

content.content:
1	-- bipar_lote_scanner: processa um lote inteiro de containers do Scanner QR numa única chamada.
2	-- Antes o frontend fazia ~3 round-trips por caixa (SELECT estoque + RPC bipar_etiqueta + INSERT
3	-- movimentacoes); esta função troca tudo por 1 chamada por lote.
4	--
5	-- Atribuicao de usuario: chama get_usuario_id_from_auth(auth.uid()) de forma INEQUIVOCA
6	-- (a funcao tem 2 overloads — chamar sem arg dava "function is not unique") e dentro de bloco
7	-- de excecao — atribuir usuario NUNCA derruba a entrada. Antes o Scanner deixava usuario_id NULL,
8	-- entao a coluna "Responsável" da lista ficava vazia.
9	--
10	-- QTY AUTORITATIVA: quando ha uid, a quantidade vem da propria etiqueta
11	-- (quantidade_disponivel; senao quantidade_interna) — a caixa sabe quantas unidades tem.
12	-- Garante +40 (o conteudo real), nunca +1 por payload incompleto.
13	--
14	-- Cada item e' isolado em seu proprio bloco de excecao: 1 item ruim nao derruba o lote.
15	
16	CREATE OR REPLACE FUNCTION public.bipar_lote_scanner(
17	    p_loja_id integer,
18	    p_tipo text,
19	    p_itens jsonb
20	)
21	RETURNS jsonb
22	LANGUAGE plpgsql
23	SECURITY DEFINER
24	SET search_path TO 'public'
25	AS $$
26	DECLARE
27	    v_usuario_id integer;
28	    v_item jsonb;
29	    v_id text;
30	    v_pid integer;
31	    v_uid text;
32	    v_lote_id uuid;
33	    v_qty numeric;
34	    v_disp numeric;
35	    v_interna numeric;
36	    v_tipo_embalagem text;
37	    v_embalagem_nome text;
38	    v_lote text;
39	    v_payload jsonb;
40	    v_saldo_anterior numeric;
41	    v_saldo_novo numeric;
42	    v_motivo text;
43	    v_observacoes text;
44	    v_resultados jsonb := '[]'::jsonb;
45	    v_ok integer := 0;
46	    v_err integer := 0;
47	BEGIN
48	    -- Atribuicao de usuario: chamada inequivoca (1 arg) + nunca fatal.
49	    BEGIN
50	        v_usuario_id := public.get_usuario_id_from_auth(auth.uid());
51	    EXCEPTION WHEN OTHERS THEN
52	        v_usuario_id := NULL;
53	    END;
54	
55	    -- Itera NA ORDEM do array: o trigger AFTER INSERT em movimentacoes atualiza `estoque`,
56	    -- entao re-selecionar `estoque` a cada item da o saldo corrente correto na mesma transacao
57	    -- (varios containers do mesmo produto acumulam saldo na sequencia certa).
58	    FOR v_item IN SELECT * FROM jsonb_array_elements(p_itens)
59	    LOOP
60	        v_id := v_item->>'id';
61	        BEGIN
62	            v_pid := (v_item->>'pid')::integer;
63	            v_uid := NULLIF(v_item->>'uid', '');
64	            v_lote_id := NULLIF(v_item->>'lote_id', '')::uuid;
65	            v_qty := (v_item->>'qty')::numeric;
66	            v_tipo_embalagem := NULLIF(v_item->>'tipo_embalagem', '');
67	            v_embalagem_nome := NULLIF(v_item->>'embalagem_nome', '');
68	            v_lote := NULLIF(v_item->>'lote', '');
69	            v_payload := v_item->'payload';
70	
71	            -- Atualiza status da etiqueta (reaproveita RPC; backfill garante a linha existir).
72	            -- Nao mexe em estoque/movimentacoes; ok=false e' so warning; excecao nao derruba o item.
73	            IF v_uid IS NOT NULL THEN
74	                BEGIN
75	                    PERFORM public.bipar_etiqueta(
76	                        v_uid,
77	                        CASE WHEN p_tipo = 'entrada' THEN 'entrada' ELSE 'saida' END,
