-- ============================== TABELAS ======================================

-- núcleo / multi-loja
COMMENT ON TABLE public.lojas IS 'Cadastro das lojas/unidades (multi-loja). 1=Fábrica,2=Asa Sul,3=Asa Norte,4=Lago Sul,5=Águas Claras,6=Brasília Shopping.';

-- estoque & movimentações
