COMMENT ON TABLE public.alertas_estoque IS 'Alertas gerados quando estoque cruza mínimo/máximo (ex.: estoque baixo, ruptura). Marcados como resolvidos ao normalizar.';
COMMENT ON TABLE public.setores IS 'Setores operacionais (ex.: produção, confeitaria) usados para classificar produtos, categorias e etapas.';
COMMENT ON TABLE public.lotes IS 'Lotes de produto com código, validade e fabricação. Base da rastreabilidade por validade (shelf-life curto, doces saudáveis).';
COMMENT ON TABLE public.estoque_lotes IS 'Saldo de estoque por lote e por loja (quanto resta de cada lote em cada unidade).';
COMMENT ON TABLE public.perdas IS 'Registro de perdas/quebras de produto (motivo, valor estimado, foto), com fluxo de verificação. Multi-loja.';
COMMENT ON TABLE public.perdas_produtos IS 'Lista de produtos elegíveis para registro de perdas (catálogo auxiliar da tela de Perdas).';
COMMENT ON TABLE public.produto_loja_visibility IS 'Define quais produtos_master estão visíveis/ativos em cada loja. Sem linha ativa o produto some da busca da loja.';
COMMENT ON TABLE public.produto_legacy_mapping IS 'Mapeamento de produtos legados (produtos.id antigo) para o respectivo produto_master_id, por loja.';
COMMENT ON TABLE public.produto_sales_mapping IS 'Mapeia nomes/códigos de produto do PDV/vendas para produto_master_id, com status de conferência do match.';
COMMENT ON TABLE public.produto_aliases IS 'Apelidos/sinônimos de produtos aprendidos pelo matcher da requisição manual (fuzzy match), com contador de uso.';
COMMENT ON TABLE public.historico_vendas IS 'Histórico diário de vendas por produto e loja (qtd, valor, dia da semana). Base para forecast/DRP.';
COMMENT ON TABLE public.ncm_produtos IS 'Cadastro de NCM (classificação fiscal) e custo por produto/loja, usado em notas e tributação.';
COMMENT ON TABLE public.pronta_entrega_stock IS 'Estoque de pronta-entrega exposto na loja (produto, quantidade, validade, localização) para venda imediata.';
COMMENT ON TABLE public.pronta_entrega_logs IS 'Log de ações na pronta-entrega (entradas, baixas, ajustes) por usuário e loja.';

-- requisições (lojas pedem à fábrica) & separação
COMMENT ON TABLE public.requisicoes IS 'Requisições de mercadoria que as lojas fazem à fábrica (cabeçalho: solicitante, preparador, lojas, datas, status, pipeline).';
COMMENT ON TABLE public.requisicoes_itens IS 'Itens de uma requisição (produto, qtd solicitada/enviada/recebida, separação, lote, validade).';
COMMENT ON TABLE public.requisition_pipelines IS 'Pipeline (workflow) de execução de uma requisição com etapas e coordenador. Fluxo estruturado de separação.';
COMMENT ON TABLE public.pipeline_funcionarios IS 'Funcionários alocados a cada etapa de um requisition_pipeline (papel e etapa atual).';
COMMENT ON TABLE public.pipeline_etapa_logs IS 'Log de ações/transições por etapa do requisition_pipeline (auditoria do workflow de separação).';
COMMENT ON TABLE public.pipeline_separacao_itens IS 'Itens separados por colaborador dentro de uma etapa do requisition_pipeline (qtd separada, status).';
COMMENT ON TABLE public.active_sessions IS 'Sessões de separação digital colaborativa em tempo real (cabeçalho: lojas, datas, status, expiração).';
COMMENT ON TABLE public.active_session_items IS 'Itens de uma sessão de separação digital (qtd solicitada/enviada, separado, bip de etiqueta QR).';
COMMENT ON TABLE public.active_review_sessions IS '(?) Sessões de conferência/revisão de separação ativas (cabeçalho temporário com expiração).';
COMMENT ON TABLE public.digital_separations IS 'Separações digitais (registro consolidado de uma sessão de separação concluída).';
COMMENT ON TABLE public.digital_separation_items IS 'Itens de uma separação digital (snapshot dos itens separados a partir da sessão).';
COMMENT ON TABLE public.digital_separation_users IS 'Usuários participando de uma separação digital colaborativa (presença em tempo real, cor de identificação).';
COMMENT ON TABLE public.expedicoes IS 'Expedições/rotas de entrega (Torre de Controle): agendamento, veículo, motorista, status.';
COMMENT ON TABLE public.expedicao_logs IS 'Log de eventos de uma expedição (saída, parada, entrega) vinculado a requisições. Timeline da Torre de Controle.';

-- produção diária & PCP
COMMENT ON TABLE public.daily_production IS 'Produção diária registrada (produto, quantidade, data). loja_id NULL = fábrica (produção centralizada).';
COMMENT ON TABLE public.daily_production_products IS 'Produtos elegíveis para registro de produção diária por loja (lista da tela de produção).';
COMMENT ON TABLE public.daily_production_exclusions IS 'Produtos excluídos da lista de produção diária de uma loja.';
COMMENT ON TABLE public.weekly_production_plan IS 'Plano semanal de produção por loja/produto: demanda calculada, ajuste manual e produção final.';
COMMENT ON TABLE public.insumos IS 'Insumos/matérias-primas para produção: unidades de compra/produção, fatores de conversão e correção, custo, alérgenos.';
COMMENT ON TABLE public.fichas_tecnicas IS 'Fichas técnicas (receitas/BOM) de produtos: versão, rendimento, fator de rendimento, custo calculado.';
COMMENT ON TABLE public.ficha_tecnica_itens IS 'Itens de uma ficha técnica: insumo, sub-ficha (semi-acabado) ou produto, com quantidade, unidade e custo.';
COMMENT ON TABLE public.ficha_tecnica_etapas IS 'Etapas do processo produtivo de uma ficha técnica (ordem, setor, duração, temperatura, instruções).';
COMMENT ON TABLE public.ordens_producao IS 'Ordens de produção (OP): quantidades planejada/produzida/perdida, custos previsto/real, variância, lote e validade.';
COMMENT ON TABLE public.op_insumos IS 'Consumo de insumos por ordem de produção (qtd prevista x consumida, custo unitário e total).';
COMMENT ON TABLE public.op_perdas IS 'Perdas registradas por etapa dentro de uma ordem de produção (categoria, quantidade).';
COMMENT ON TABLE public.recipe_canvas_positions IS 'Posições (x,y) dos nós no canvas visual do construtor de fichas técnicas, por workspace.';

-- encomendas & eventos
COMMENT ON TABLE public.encomendas IS 'Encomendas de clientes (delivery/retirada) com cliente, itens, entrega, pagamento e recorrência. Pode ter origem na Noaa.';
COMMENT ON TABLE public.eventos IS 'Eventos comerciais (feiras, ações externas) com data, local, responsável, faturamento e recorrência.';
COMMENT ON TABLE public.eventos_produtos IS 'Produtos enviados/separados para um evento (qtd enviada, retorno, perda, verificação).';
COMMENT ON TABLE public.eventos_custos IS 'Custos lançados em um evento (descrição, valor, tipo, anexo).';
COMMENT ON TABLE public.eventos_anexos IS 'Anexos/arquivos vinculados a um evento.';
COMMENT ON TABLE public.eventos_transacoes IS 'Transações financeiras (receitas/despesas) de um evento com categoria e comprovante.';
COMMENT ON TABLE public.eventos_perdas IS 'Perdas de produto registradas em um evento (produto, quantidade, motivo).';
COMMENT ON TABLE public.eventos_esocial IS 'Eventos eSocial gerados para um funcionário (XML, status de transmissão, resposta). Módulo RH.';
COMMENT ON TABLE public.orcamentos_gerados IS 'Orçamentos gerados para clientes (itens em JSON, valor total, desconto).';
COMMENT ON TABLE public.event_changelogs IS 'Changelog/auditoria de alterações em entidades de eventos e encomendas (ação, descrição, detalhes, autor).';
COMMENT ON TABLE public.acoes_marketing IS 'Ações de marketing com saída de produtos (degustação, cupom, embaixador, brinde, ação promocional etc.), com valor estimado e verificação.';

-- logística (calendários/agenda)
COMMENT ON TABLE public.logistica_events IS '(?) Eventos de agenda logística simples (título, janela de tempo, loja). Provável modelo antigo de calendário.';
COMMENT ON TABLE public.logistica_calendarios IS 'Calendários da agenda de logística (nome, cor, padrão).';
COMMENT ON TABLE public.logistica_eventos IS 'Eventos da agenda de logística vinculados a um calendário (início/fim, dia inteiro, local).';

